CREATE TABLE IF NOT EXISTS p10_scene_presence (player_id BIGINT PRIMARY KEY, scene VARCHAR(64) NOT NULL, line INT NOT NULL, session_hash CHAR(64) NOT NULL, frame LONGBLOB NOT NULL, updated_at BIGINT NOT NULL, offline_until BIGINT NOT NULL DEFAULT 0, offline_pk_used BOOLEAN NOT NULL DEFAULT FALSE, INDEX(scene), INDEX(line), KEY idx_p10_scene_visibility (scene,line,session_hash,offline_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
